def page_inicio():
    df=read_df('SELECT * FROM pnc_registros')
    if df.empty: df=pd.DataFrame(columns=['fecha_apertura','status','linea_sector','clasificacion','material_hallado','cantidad_total_pnc'])
    df['fecha_apertura']=pd.to_datetime(df['fecha_apertura'],errors='coerce')
    st.markdown('<div class="home-hero"><div class="home-hero-title">Panel Calidad Mundo Dulce</div></div>',unsafe_allow_html=True)
    with st.expander('Filtros dinámicos de indicadores',expanded=False):
        a,b,c,d=st.columns(4); fs=a.multiselect('Status',sorted(df['status'].dropna().unique())); fl=b.multiselect('Línea/Sector',sorted(df['linea_sector'].dropna().unique())); fc=c.multiselect('Clasificación',sorted(df['clasificacion'].dropna().unique())); focus=d.radio('Enfoque',['Todos','Abiertos','Cerrados','Con ME'])
    data=df.copy()
    if fs: data=data[data['status'].isin(fs)]
    if fl: data=data[data['linea_sector'].isin(fl)]
    if fc: data=data[data['clasificacion'].isin(fc)]
    if focus=='Abiertos': data=data[data['status']=='ABIERTO']
    if focus=='Cerrados': data=data[data['status']=='CERRADO']
    if focus=='Con ME': data=data[data['material_hallado'].fillna('').astype(str).str.len()>0]
    total=len(data); abiertos=int((data['status']=='ABIERTO').sum()) if not data.empty else 0; cerrados=int((data['status']=='CERRADO').sum()) if not data.empty else 0; me=int(data['material_hallado'].fillna('').astype(str).str.len().gt(0).sum()) if not data.empty else 0; kg=float(data['cantidad_total_pnc'].fillna(0).sum()) if not data.empty else 0; avance=int(cerrados/total*100) if total else 0
    k1,k2,k3,k4=st.columns(4)
    with k1: st.markdown(f'<div class="kpi" style="--c:#00A884"><div class="kpi-label">PNC abiertos</div><div class="kpi-value">{abiertos}</div><div class="kpi-foot">Registros pendientes</div></div>',unsafe_allow_html=True)
    with k2: st.markdown(f'<div class="kpi" style="--c:#5850EC"><div class="kpi-label">Avance de cierre</div><div class="kpi-value">{avance}%</div><div class="kpi-foot">Cerrados vs total</div></div>',unsafe_allow_html=True)
    with k3: st.markdown(f'<div class="kpi" style="--c:#F59E0B"><div class="kpi-label">Registros filtrados</div><div class="kpi-value">{total}</div><div class="kpi-foot">Coincidencias</div></div>',unsafe_allow_html=True)
    with k4: st.markdown(f'<div class="kpi" style="--c:#E11D48"><div class="kpi-label">Kg PNC / ME</div><div class="kpi-value">{kg:,.1f}</div><div class="kpi-foot">Hallazgos ME: {me}</div></div>',unsafe_allow_html=True)
    l,r=st.columns([2,1])
    with l:
        st.markdown('<div class="panel"><div class="panel-header">Tendencia mensual dinámica</div><div class="panel-body">',unsafe_allow_html=True)
        if not data.empty:
            t=data.dropna(subset=['fecha_apertura']).copy(); t['Mes']=t['fecha_apertura'].dt.strftime('%Y-%m'); st.bar_chart(t.groupby(['Mes','status']).size().unstack(fill_value=0),use_container_width=True)
        else: st.info('No hay registros para graficar.')
        st.markdown('</div></div>',unsafe_allow_html=True)
    with r:
        st.markdown('<div class="panel"><div class="panel-header">Distribución por clasificación</div><div class="panel-body">',unsafe_allow_html=True)
        if not data.empty: st.dataframe(data['clasificacion'].fillna('Sin clasificación').value_counts().rename_axis('Clasificación').reset_index(name='Registros'),use_container_width=True,hide_index=True)
        else: st.info('No hay datos.')
        st.markdown('</div></div>',unsafe_allow_html=True)

def page_registro():
    st.title('Nuevo registro PNC / ME')
    prod=read_df('SELECT * FROM productos WHERE activo=1 ORDER BY descripcion'); defs=read_df('SELECT * FROM defectos WHERE activo=1 ORDER BY CAST(codigo AS INTEGER)')
    with st.form('registro'):
        c1,c2,c3=st.columns(3)
        fecha=c1.date_input('Fecha',value=date.today()); linea=c1.selectbox('Línea/Sector',catalog('linea_sector')); nave=c1.selectbox('Nave',catalog('nave'))
        opt=c2.selectbox('ITEM / Producto',[f'{r.item} | {r.descripcion}' for r in prod.itertuples()]) if not prod.empty else ''
        item=opt.split('|')[0].strip() if opt else c2.text_input('ITEM')
        row=prod[prod['item']==item].iloc[0] if not prod.empty and item in prod['item'].values else None
        desc=str(row['descripcion']) if row is not None else c2.text_input('Descripción'); cliente=str(row['cliente']) if row is not None else ''; familia=str(row['familia']) if row is not None else ''
        lote=c2.text_area('Lote'); etapa=c3.selectbox('Etapa',catalog('etapa')); turno=c3.selectbox('Turno',catalog('turno')); status=c3.selectbox('Status',catalog('status'))
        optd=st.selectbox('Código / Defecto',[f'{r.codigo} | {r.defecto}' for r in defs.itertuples()]) if not defs.empty else ''
        cod=optd.split('|')[0].strip() if optd else st.text_input('Código')
        dr=defs[defs['codigo']==cod].iloc[0] if not defs.empty and cod in defs['codigo'].values else None
        defecto=str(dr['defecto']) if dr is not None else ''; tipo=str(dr['tipo_defecto']) if dr is not None else ''; clas=str(dr['clasificacion']) if dr is not None else ''
        descripcion=st.text_area('Descripción del defecto'); acciones=st.text_area('Acciones inmediatas',value='Se detiene línea, se segrega e identifica el producto.')
        c4,c5,c6=st.columns(3); sup=c4.selectbox('Supervisor',catalog('supervisor')); ana=c4.selectbox('Analista',catalog('analista')); resp=c5.selectbox('Responsable detecta',catalog('responsable_detecta')); disp=c5.selectbox('Disposición',catalog('disposicion')); fecha_final=c6.date_input('Fecha final',value=date.today()) if status=='CERRADO' else None
        q1,q2,q3,q4=st.columns(4); obs=q1.number_input('Observada kg',min_value=0.0); rep=q2.number_input('Reproceso kg',min_value=0.0); dec=q3.number_input('Decomiso kg',min_value=0.0); apr=q4.number_input('Aprobado 2da kg',min_value=0.0); total=rep+dec+apr
        mat=st.text_area('Material hallado / ME'); notas=st.text_area('Observaciones'); files=st.file_uploader('Adjuntar evidencia',accept_multiple_files=True,type=['pdf','png','jpg','jpeg','xlsx','csv','txt','docx']); ok=st.form_submit_button('Guardar registro')
    if ok:
        folio=new_folio(); rid=exec_sql('INSERT INTO pnc_registros(folio,fecha_apertura,linea_sector,nave,item,descripcion_producto,cliente,familia,lote,etapa,codigo_defecto,defecto,tipo_defecto,clasificacion,turno,supervisor,analista,responsable_detecta,descripcion_defecto,acciones_inmediatas,disposicion,cantidad_observada,cantidad_reproceso,cantidad_decomiso,cantidad_aprobado_segunda,cantidad_total_pnc,status,fecha_final_tratamiento,observaciones,material_hallado,creado_por,creado_en) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',(folio,fecha.isoformat(),linea,nave,item,desc,cliente,familia,lote,etapa,cod,defecto,tipo,clas,turno,sup,ana,resp,descripcion,acciones,disp,obs,rep,dec,apr,total,status,fecha_final.isoformat() if fecha_final else None,notas,mat,st.session_state.auth['usuario'],now_iso()))
        save_files(files,rid,folio,st.session_state.auth['usuario']); audit(st.session_state.auth['usuario'],'CREAR_PNC',folio); st.success(f'Registro guardado correctamente: {folio}')

def page_consulta():
    st.title('Consulta, seguimiento y descarga'); df=read_df('SELECT * FROM pnc_registros ORDER BY id DESC')
    if df.empty: st.info('No hay registros capturados.'); return
    st.dataframe(df,use_container_width=True,hide_index=True); st.download_button('Descargar registros CSV',df.to_csv(index=False).encode('utf-8-sig'),f"pnc_me_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv",'text/csv')

def admin_required():
    if not is_dev(): st.warning('Solo el usuario administrador puede modificar catálogos.'); return False
    return True

def general_catalog_dataframe():
    m={'Supervisores':'supervisor','Analistas':'analista','Nave':'nave','Status':'status','Responsable de detectar PNC':'responsable_detecta','Etapa':'etapa','Línea':'linea_sector','Turno':'turno','Defecto':'tipo_defecto','Disposición':'disposicion'}
    data={}; mx=0
    for h,c in m.items(): data[h]=catalog(c); mx=max(mx,len(data[h]))
    return pd.DataFrame({h:v+['']*(mx-len(v)) for h,v in data.items()})

def page_catalogos():
    st.title('Catálogos'); st.caption('Datos precargados desde el Excel adjunto. El administrador puede agregar o eliminar elementos.')
    tab1,tab2,tab3=st.tabs(['Productos','Defectos','Datos generales'])
    with tab1:
        df=read_df('SELECT id,item,descripcion,cliente,familia FROM productos WHERE activo=1 ORDER BY descripcion'); st.dataframe(df,use_container_width=True,hide_index=True)
        if admin_required():
            with st.expander('Agregar producto'):
                with st.form('add_prod'):
                    item=st.text_input('Item'); desc=st.text_input('Descripción'); cliente=st.text_input('Cliente'); familia=st.text_input('Familia')
                    if st.form_submit_button('Agregar producto') and item and desc: exec_sql('INSERT OR REPLACE INTO productos(item,descripcion,cliente,familia,activo) VALUES(?,?,?,?,1)',(item.strip(),desc.strip(),cliente.strip(),familia.strip())); st.rerun()
            if not df.empty:
                opt=st.selectbox('Producto a eliminar',[f'{r.id} | {r.item} | {r.descripcion}' for r in df.itertuples()],key='del_prod')
                if st.button('Eliminar producto seleccionado'): exec_sql('UPDATE productos SET activo=0 WHERE id=?',(int(opt.split('|')[0].strip()),)); st.rerun()
    with tab2:
        df=read_df('SELECT id,codigo,defecto,tipo_defecto,clasificacion FROM defectos WHERE activo=1 ORDER BY CAST(codigo AS INTEGER)'); st.dataframe(df,use_container_width=True,hide_index=True)
        if admin_required():
            with st.expander('Agregar defecto'):
                with st.form('add_def'):
                    codigo=st.text_input('Código'); defecto=st.text_input('Defecto'); tipo=st.selectbox('Tipo',catalog('tipo_defecto') or ['Funcional','Contaminación']); clas=st.selectbox('Clasificación',['Inocuidad','Calidad','Salubridad','Legalidad'])
                    if st.form_submit_button('Agregar defecto') and codigo and defecto: exec_sql('INSERT OR REPLACE INTO defectos(codigo,defecto,tipo_defecto,clasificacion,activo) VALUES(?,?,?,?,1)',(codigo.strip(),defecto.strip(),tipo,clas)); st.rerun()
            if not df.empty:
                opt=st.selectbox('Defecto a eliminar',[f'{r.id} | {r.codigo} | {r.defecto}' for r in df.itertuples()],key='del_def')
                if st.button('Eliminar defecto seleccionado'): exec_sql('UPDATE defectos SET activo=0 WHERE id=?',(int(opt.split('|')[0].strip()),)); st.rerun()
    with tab3:
        st.subheader('Datos generales'); st.dataframe(general_catalog_dataframe(),use_container_width=True,hide_index=True)
        if admin_required():
            labels={'Supervisores':'supervisor','Analistas':'analista','Nave':'nave','Status':'status','Responsable de detectar PNC':'responsable_detecta','Etapa':'etapa','Línea':'linea_sector','Turno':'turno','Defecto':'tipo_defecto','Disposición':'disposicion'}
            with st.expander('Agregar valor a datos generales'):
                with st.form('add_general'):
                    lab=st.selectbox('Lista',list(labels.keys())); val=st.text_input('Nuevo valor')
                    if st.form_submit_button('Agregar valor') and val.strip(): exec_sql('INSERT OR IGNORE INTO catalogos(categoria,valor,activo) VALUES(?,?,1)',(labels[lab],val.strip())); st.rerun()
            raw=read_df('SELECT id,categoria,valor FROM catalogos WHERE activo=1 ORDER BY categoria,valor'); raw['lista']=raw['categoria'].map({v:k for k,v in labels.items()}); raw=raw.dropna(subset=['lista'])
            if not raw.empty:
                opt=st.selectbox('Valor a eliminar',[f'{r.id} | {r.lista} | {r.valor}' for r in raw.itertuples()],key='del_general')
                if st.button('Eliminar valor seleccionado'): exec_sql('UPDATE catalogos SET activo=0 WHERE id=?',(int(opt.split('|')[0].strip()),)); st.rerun()

def page_usuarios(): st.title('Usuarios'); st.dataframe(read_df('SELECT id,usuario,nombre,rol,activo,creado_en FROM usuarios ORDER BY id'),use_container_width=True,hide_index=True)
def page_auditoria(): st.title('Auditoría'); st.dataframe(read_df('SELECT * FROM auditoria ORDER BY id DESC LIMIT 1000'),use_container_width=True,hide_index=True)

def main():
    init_state(); init_db()
    if FORCE_RESET_ADMIN: reset_admin()
    user=login()
    styles(st.session_state.compact)
    left_ratio, right_ratio = (0.24, 0.76) if not st.session_state.compact else (0.075, 0.925)
    left_col, right_col = st.columns([left_ratio, right_ratio], gap='medium')
    with left_col:
        left_menu()
    with right_col:
        topbar(user)
        page=st.session_state.page
        if page=='Inicio': page_inicio()
        elif page=='Nuevo registro': page_registro()
        elif page=='Consulta y descarga': page_consulta()
        elif page=='Catálogos': page_catalogos()
        elif page=='Usuarios': page_usuarios()
        elif page=='Auditoría': page_auditoria()

if __name__=='__main__': main()
